// CSS critico per la Home
const cssHome = `
body{margin:0;padding:0;background:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif}
header{background:#333;color:#fff;padding:1rem}
.site-title{margin:0;font-size:2rem}
main{max-width:1200px;margin:0 auto;padding:1rem}
.post-list{display:grid;gap:2rem}
.post-card{border:1px solid #e0e0e0;border-radius:8px;overflow:hidden}
.post-card h2{margin:0;padding:1rem;font-size:1.5rem}
.post-card img{width:100%;height:auto;display:block}
`;

