// ============================================
// CLASS: CSS Injector
// ============================================
class CSSInjector {
  constructor(css) {
    this.css = css;
  }
  
  element(element) {
    // Inserisce il CSS critico all'inizio del <head>
    element.prepend(`<style id="critical-css">${this.css}</style>`, { html: true });
  }
}

// ============================================
// HELPER: Determina il tipo di pagina
// ============================================
function getPageType(pathname) {
  // Homepage
  if (pathname === "/" || pathname === "/index.php") {
    return "home";
  }
  
  // Pagine WordPress da escludere (amministrazione, API, assets)
  if (pathname.match(/^\/(wp-admin|wp-content|wp-includes|wp-json|feed|xmlrpc)/)) {
    return null;
  }
  
  // Categorie
  if (pathname.startsWith("/category/") || pathname.startsWith("/cat/")) {
    return "archive";
  }
  
  // Tag
  if (pathname.startsWith("/tag/")) {
    return "archive";
  }
  
  // Archivi autore
  if (pathname.startsWith("/author/")) {
    return "archive";
  }
  
  // Archivi per data (es: /2024/01/)
  if (pathname.match(/^\/\d{4}\/(\d{2}\/?)?$/)) {
    return "archive";
  }
  
  // Paginazione (es: /page/2/)
  if (pathname.match(/^\/page\/\d+\/?$/)) {
    return "home";
  }
  
  // Post singoli con struttura permalink data (es: /2024/01/15/titolo-post/)
  if (pathname.match(/^\/\d{4}\/\d{2}\/\d{2}\/[^/]+\/?$/)) {
    return "post";
  }
  
  // Post singoli con struttura permalink semplice (es: /titolo-post/)
  if (pathname.match(/^\/[^/]+\/?$/) && !pathname.match(/\.(xml|json|txt|ico)$/)) {
    return "post";
  }
  
  // Default per altri casi (pagine statiche, ecc.)
  return null;
}

// ============================================
// WORKER: Main Handler
// ============================================
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    
    // Fetch della risposta originale da WordPress
    const response = await fetch(request);
    
    // Verifica che sia una risposta HTML valida
    const contentType = response.headers.get("content-type");
    if (!contentType || !contentType.includes("text/html")) {
      return response;
    }
    
    // Solo per risposte 200 OK
    if (response.status !== 200) {
      return response;
    }
    
    // Determina il tipo di pagina
    const pageType = getPageType(url.pathname);
    
    // Se non è un tipo di pagina riconosciuto, ritorna la risposta originale
    if (!pageType) {
      return response;
    }
    
    // Seleziona il CSS critico appropriato
    let criticalCSS = "";
    switch (pageType) {
      case "home":
        criticalCSS = cssHome;
        break;
      case "post":
        criticalCSS = cssPost;
        break;
      case "archive":
        criticalCSS = cssArchive;
        break;
    }
    
    // Se non c'è CSS da iniettare, ritorna la risposta originale
    if (!criticalCSS) {
      return response;
    }
    
    // Inietta il CSS critico e ritorna la risposta modificata
    return new HTMLRewriter()
      .on("head", new CSSInjector(criticalCSS))
      .transform(response);
  },
};